head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > P > tooltipFormatter]<br/>툴팁 내용을 동적으로 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [                
        "툴팁 내용을 생성할 사용자 정의 함수를 설정합니다.",
        "tooltip, tooltipDisplay, tooltipShowAlways 속성에 의한 툴팁 모두에 적용됩니다.",
        "tooltip 속성의 툴팁으로 실행된 사용자 정의 함수는 컴포넌트의 렌더링 ID 와 툴팁 텍스트 값을 파라미터로 전달 받습니다.",
        "tooltipDisplay, tooltipShowAlways 속성의 툴팁으로 실행된 사용자 정의 함수는 아이템의 라벨값과 인덱스값을 파라미터로 전달 받습니다.",
        "사용자 정의 함수의 반환값이 새로운 툴팁 텍스트로 적용됩니다.",
        "사용자 정의 함수의 반환값이 tooltip 속성과 tooltipDisplay, tooltipShowAlways 속성에 의한 툴팁에 각각 반영됩니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        tooltip: con_tooltip.getValue(),        
        tooltipDisplay: con_tooltipDisplay.getText(),
        tooltipFormatter: con_tooltipFormatter.getText(),
        tooltipShowAlways: con_tooltipShowAlways.getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);     

    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" dataType="listed" tooltipGroupClass="false" style="width:200px;">';
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref=""></w2:folder>';
    strTarget += '<w2:checkbox ref=""></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref=""></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    ); 
}



scwin.fn_tooltip = function (id, text) {
    return "id - " + id + ", tooltip - " + text;       
}



scwin.target1_onclick = function () { 
    $c.gcm.getTooltipInfo(wf_body_bottom);
}
